"""Build a three-scope local comparison from complete, answer-bound reviews."""
import csv,hashlib,html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(sys.argv[1]).resolve();read=lambda root,n:json.loads((root/n).read_text());h=lambda x:html.escape(str(x),quote=True)
P=read(R,'protocol.json');cases=read(R,'cases.json');review=read(R,'reviewed-judgments.json');rows=read(R,'artifacts/all-results.json')['rows'];g={x['trial_id']:x for x in review['rows']}
scopes=[]
for name,folder,col,marker in [('Output only','2026-10-19-answerable-abstention','#8c668a','o'),('Input + output','2026-10-19-answerable-all-token','#087765','D'),('Input only','2026-10-19-answerable-input-only','#c47824','^')]:
 root=R.parent/folder;rs=read(root,'artifacts/all-results.json')['rows'];gs={x['trial_id']:x for x in read(root,'reviewed-judgments.json')['rows']};scopes.append((name,root,col,marker,rs,gs))
common=[1,2,4,8,16,24,32,48,64];matched=[]
for name,_,col,marker,rs,gs in scopes:
 for a in common:
  xs=[r for r in rs if r['added_gate']==a];assert len(xs)==10
  matched.append({'scope':name,'strength':a,'full_abstention':sum(gs[r['trial_id']]['false_abstention'] for r in xs),'mixed':sum(gs[r['trial_id']]['category']=='mixed' for r in xs),'coherent':sum(gs[r['trial_id']]['coherent'] for r in xs)})
(R/'matched-strength-counts.json').write_text(json.dumps(matched,indent=2)+'\n')
fig,axes=plt.subplots(1,3,figsize=(15,5),sharey=True)
for ax,key,title in zip(axes,['full_abstention','mixed','coherent'],['Clear answer-free abstention','Answer + uncertainty / caveat','Coherent response']):
 for i,(name,root,col,marker,rs,gs) in enumerate(scopes):
  xs=[x for x in matched if x['scope']==name];ax.scatter([x['strength']+(i-1)*.5 for x in xs],[x[key] for x in xs],color=col,marker=marker,s=57,label=name,edgecolor='white',linewidth=.6)
 ax.set_title(title);ax.set_xlabel('Added coefficient a');ax.set_xticks([1,8,16,24,32,48,64]);ax.set_ylim(-.5,10.6);ax.set_yticks([0,2,4,6,8,10]);ax.grid(alpha=.15);ax.spines[['top','right']].set_visible(False)
axes[0].set_ylabel('Questions out of 10');axes[1].legend(loc='upper center',bbox_to_anchor=(.5,-.23),ncol=3,frameon=False,fontsize=10)
fig.suptitle('L19–T368 · Can prompt steering alone cause answer-free abstention?',fontsize=16);fig.subplots_adjust(top=.8,bottom=.28,wspace=.1);fig.savefig(R/'three-scope-comparison.png',dpi=165,facecolor='white');plt.close(fig)
colors={'correct':'#367394','abstention':'#087765','mixed':'#8c668a','broken':'#b24c42','wrong':'#b17b2e','other':'#777c78','question_drift':'#c47824'};labels={'correct':'Correct answer','abstention':'Clear answer-free abstention','mixed':'Answer + uncertainty / caveat','broken':'Incoherent / repetitive','wrong':'Wrong answer','other':'Other','question_drift':'Readable refusal · question drift'}
positive=[r for r in rows if r['added_gate'] is not None and r['added_gate']>0]
fig,ax=plt.subplots(figsize=(13,6))
for cat in colors:
 xs=[r for r in positive if g[r['trial_id']]['category']==cat]
 if xs:ax.scatter([r['added_gate'] for r in xs],[[c['id'] for c in cases].index(r['case_id']) for r in xs],color=colors[cat],s=58,label=labels[cat],edgecolor='white',linewidth=.6)
ax.set_title('Input-only steering · every tested coefficient and question',fontsize=16,pad=18);ax.set_xlabel('Positive coefficient added during prompt processing only');ax.set_xlim(-1,66);ax.set_xticks([0,4,8,12,16,20,24,28,32,40,48,56,64]);ax.set_yticks(range(10),[c['id'] for c in cases]);ax.invert_yaxis();ax.grid(alpha=.15);ax.spines[['top','right']].set_visible(False);ax.legend(loc='upper center',bbox_to_anchor=(.5,-.15),ncol=3,frameon=False);fig.subplots_adjust(left=.09,right=.98,top=.86,bottom=.24);fig.savefig(R/'input-only-outcomes.png',dpi=165,facecolor='white');plt.close(fig)
summary=[];cards=[]
for c in cases:
 statuses={};boxes=[];chosen_new=None
 for name,root,col,marker,rs,gs in scopes:
  xs=[r for r in rs if r['case_id']==c['id'] and r['added_gate'] is not None and r['added_gate']>0];good=[r for r in xs if gs[r['trial_id']]['false_abstention']]
  preferred=[r for r in good if gs[r['trial_id']]['additional_false_facts'] is False];chosen=min(preferred or good,key=lambda r:r['added_gate']) if good else None
  if name=='Input only':
   if not chosen:chosen=next((r for r in xs if r['trial_id']==review.get('representative_failures',{}).get(c['id'])),None)
   chosen_new=chosen
  elif not chosen:
   old=read(root,'summary.json');item=next(x for x in old['per_case'] if x.get('id',x.get('case_id'))==c['id']);chosen=next((r for r in xs if r['trial_id']==item['selected_trial_id']),None)
  statuses[name]={'full_abstention_found':bool(good),'successful_tested_strengths':sorted(r['added_gate'] for r in good),'common_grid_success':any(r['added_gate'] in common for r in good),'selected_trial_id':chosen['trial_id'] if chosen else None,'selected_strength':chosen['added_gate'] if chosen else None,'selected_answer':chosen['answer'] if chosen else None,'selected_question_drift':bool(chosen and gs[chosen['trial_id']].get('question_drift'))}
  if chosen:boxes.append(f'<div class="answer {"success" if good else "failure"}"><span class="label">{h(name)} · +{chosen["added_gate"]:g}</span><blockquote>{h(chosen["answer"])}</blockquote><p class="fine">{h(gs[chosen["trial_id"]]["notes"])}</p></div>')
 summary.append({'case_id':c['id'],'question':c['question'],'scopes':statuses})
 cards.append(f'<article class="example" id="case-{c["id"]}"><h3>{h(c["id"])} · {h(c["question"])}</h3><p class="fine"><b>Native correct answer:</b> {h(c["prior_native_answer"])}</p><div class="triple">{"".join(boxes)}</div><p class="fine">Representative values are separately selected per scope. See the matched-strength plots for equal-coefficient comparisons.</p></article>')
counts={name:sum(c['scopes'][name]['full_abstention_found'] for c in summary) for name,*_ in scopes};gridcounts={name:sum(c['scopes'][name]['common_grid_success'] for c in summary) for name,*_ in scopes}
report={'questions':10,'native_correct':10,'positive_trials':len(positive),'controls':20,'input_only_caveated_question_drift_cases':sorted({r['case_id'] for r in rows if g[r['trial_id']]['category']=='question_drift'}),'tuned_success_cases':counts,'common_nine_coefficient_grid_success_cases':gridcounts,'per_case':summary,'interpretation':'Full coherent answer-free withholding, on answer-present questions. These are false abstentions. Per-question tuning, not a held-out policy rate.'}
(R/'summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
with (R/'all-responses.csv').open('w') as f:
 fields=['trial_id','case_id','question','reference_answer','added_gate','answer','category','coherent','explicit_abstention','substantive_answer','false_abstention','notes'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:w.writerow({k:r[k] if k in r else g[r['trial_id']].get(k) for k in fields})
tr=''.join('<tr><th><a href="#case-'+x['case_id']+'">'+x['case_id']+'</a></th><td>'+h(x['question'])+'</td>'+''.join('<td>'+('Yes' if x['scopes'][name]['full_abstention_found'] else 'No')+'</td>' for name,*_ in scopes)+'<td>'+h(', '.join(str(a) for a in x['scopes']['Input only']['successful_tested_strengths']) or '—')+'</td></tr>' for x in summary)
trials=''.join(f'<details class="trial" id="{h(r["trial_id"])}" data-category="{g[r["trial_id"]]["category"]}"><summary>{h(r["case_id"])} · {"Native" if r["added_gate"] is None else "+"+str(r["added_gate"])} · {h(labels[g[r["trial_id"]]["category"]])}</summary><blockquote>{h(r["answer"])}</blockquote><p class="fine">{h(g[r["trial_id"]]["notes"])} Actual edited prompt positions: {r["summary"]["edited_positions"]}; edited response positions: 0. First output token unchanged: {r["first_output_token_unchanged"]}.</p></details>' for r in rows)
style='''*{box-sizing:border-box}body{margin:0;background:#faf8f1;color:#20363e;font:16px/1.65 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:40px 28px 80px}h1{font-size:clamp(32px,5vw,55px);line-height:1.1;letter-spacing:-.04em}h2{font-size:28px;margin-top:45px}h3{font-size:18px}.lead{font-size:20px;max-width:1000px}.fine{font-size:12px;color:#596d70}.label,.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.08em;font-weight:750}.note{padding:22px 26px;background:#e8f0e4;border-left:4px solid #087765;margin:25px 0}.triple{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.answer{min-width:0;padding:18px;background:#fffefa;border:1px solid #d3dbd0;border-radius:9px}.success{background:#e8f1e5}.failure{background:#f8eee6}blockquote{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.8 ui-monospace,monospace;margin:14px 0}.example{padding:20px 0;border-bottom:1px solid #d6ddd1}img{width:100%;height:auto;display:block;border:1px solid #d4dad0;border-radius:7px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px;text-align:left;border-bottom:1px solid #d5dcd1}thead{background:#e8ede4}a{color:#087765}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1b3740;color:#fff;padding:22px;font-size:13px}details{padding:16px;border:1px solid #d6ddd1;background:#fffefa;border-radius:7px;margin:10px 0}summary{cursor:pointer;font-size:13px}.links,.toolbar{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0;font-size:13px}button{padding:9px;background:white;border:1px solid #8eaaa0;color:#087765;border-radius:5px;cursor:pointer}@media(max-width:800px){main{padding:24px 16px}.triple{grid-template-columns:1fr}h1{font-size:34px}td,th{font-size:11px;padding:9px}}'''
counttable=''.join(f'<tr><th>{h(name)}</th><td>{counts[name]}/10</td><td>{gridcounts[name]}/10</td></tr>' for name,*_ in scopes)
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Input-only abstention steering · L19–T368</title><style>{style}</style></head><body><main><p class="eyebrow">Qwen3–4B · L19–T368 · 19 October 2026</p><h1>Can steering the input alone produce “I don’t know”?</h1><p class="lead">The same ten answer-present questions. Steer every input token, then generate without any response-token MLP addition.</p><div class="note"><b>{counts['Input only']}/10 questions reach clear, coherent answer-free abstention in the input-only search.</b><p>For comparison, earlier output-only steering reached {counts['Output only']}/10 and input-plus-output steering reached {counts['Input + output']}/10. These use per-question strength searches with different budgets. Equal-grid comparisons are shown separately. Two additional input-only responses are readable and omit the answer but shift the question: +48 asks about types of sedimentary rock, and +52 focuses on which rock was melted. These are separate caveated outcomes and are excluded from the three clear successes.</p></div><h2>Three intervention scopes</h2><div class="scroll"><table><thead><tr><th>Scope</th><th>Full abstention found · complete tuned search</th><th>Found · same nine coefficients</th></tr></thead><tbody>{counttable}</tbody></table></div><p>All ten native answers were correct. Twenty fresh native/zero controls match their saved token sequences exactly. The input-only study includes {len(positive)} positive trials; every complete answer is retained and reviewed. An answer followed by “I don’t know” fails the answer-free target. A readable refusal of a shifted question is classified separately as question drift, not a clear success.</p><h2>Exact input-only operation</h2><pre>During prompt processing, at every encoded input position:
z = current post-attention residual, standardized with released MOLT statistics
L(z) = ((z @ V_368) @ U_368) × output_std_19
native MLP output += a × L(z)
effective estimated gate = natural_gate(z) + a

During response-token processing:
NO MLP addition; the monitoring hook returns None.
Natural MOLT activity is not suppressed or clamped.</pre><p>All encoded input positions include the instruction, passage, question, chat markers and assistant prefix. The edited prompt predicts the first output token. The resulting KV cache is retained; subsequent response tokens use normal model computation and may attend to the altered prompt representations. This is no direct response-token steering, not a reset to an untouched prompt.</p><p>Same additive coefficient formula, native MLP, checkpoint and selected rank-128 transform as the previous two scopes. Label: “Onset of Refusal or Ignorance Statements”; IDs zero-based. Attention stays unfrozen. Thinking disabled, greedy batch one, BF16 native model and FP32 MOLT math, 96-new-token cap.</p><h2>Matched coefficients</h2><img src="three-scope-comparison.png" alt="Three scatter plots comparing abstention, mixed answers and coherence across three intervention scopes"><p class="fine">Same ten cases at each common coefficient: 1, 2, 4, 8, 16, 24, 32, 48, 64. Small horizontal marker offsets reveal overlap. Counts describe this fixed cohort, not a population estimate. Clear abstention excludes question-drift refusals. No connecting lines.</p><h2>Per-question results</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Question</th><th>Output only?</th><th>Input + output?</th><th>Input only?</th><th>Successful input-only additions</th></tr></thead><tbody>{tr}</tbody></table></div><h2>Read the actual responses</h2>{''.join(cards)}<h2>All input-only trials</h2><img src="input-only-outcomes.png" alt="Categorical scatter of every input-only coefficient and outcome"><p class="fine">A successful coefficient is a tested example, not a proven minimum. Higher strength is not assumed to improve outcomes.</p><h2>What this establishes</h2><p>The intervention tests whether prompt changes can cause the model to withhold an answer without continued direct response steering. It does not establish a general mechanism, erasure of knowledge or improved factual accuracy. Every requested answer is in the passage, so refusal here is false abstention. False absence rationales and unrelated invented facts are flagged separately from readability. The +56 remelting response is a borderline case: it declines the question but still mentions magma in its explanation. Conservatively, that counts as answer leakage, not a full conversion. Supported broad alternatives also count as disclosure.</p><p>Complete responses are reviewed by Codex with conditions visible. No independent blinded grading or unrelated-transform control is included. The audit verifies every input edit, zero direct response edits, token-identical controls, source hashes, and identical prefill traces/first predictions against the corresponding input-plus-output runs.</p><h2>Every complete input-only response</h2><div class="toolbar"><button data-filter="all">All</button><button data-filter="abstention">Full abstention</button><button data-filter="mixed">Answer + uncertainty</button><button data-filter="broken">Incoherent</button><button data-filter="question_drift">Question drift</button></div>{trials}<div class="links"><a href="all-responses.csv">Responses + reviews CSV</a><a href="artifacts/all-results.json">Raw tokens + traces</a><a href="verification.json">Verification</a><a href="reviewed-judgments.json">Reviews</a><a href="protocol.json">Protocol</a><a href="cohort.json">Passages + provenance</a><a href="summary.json">Summary</a><a href="../2026-10-19-answerable-all-token/index.html">Earlier input + output report</a></div><p class="fine">Selected SQuAD2.0 passages, CC BY-SA 4.0. GPU retained for follow-ups under the user’s instruction.</p></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('.trial').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)))</script></body></html>'''
(R/'index.html').write_text(page);print(json.dumps({k:v for k,v in report.items() if k!='per_case'},indent=2))
